begin;
create table if not exists public.tv_admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.tv_admin_notifications (id bigint generated always as identity primary key, kind text not null, provider_id uuid references public.provider_profiles(id) on delete cascade, created_at timestamptz not null default now(), read_at timestamptz);
alter table public.tv_admin_users enable row level security; alter table public.tv_admin_notifications enable row level security;
revoke all on public.tv_admin_users, public.tv_admin_notifications from anon, authenticated;
grant usage on schema public to authenticated;
create or replace function public.tv_is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.tv_admin_users where user_id = auth.uid()); $$;
revoke all on function public.tv_is_admin() from public, anon, authenticated; grant execute on function public.tv_is_admin() to authenticated;
create policy "Admins read admin users" on public.tv_admin_users for select to authenticated using (public.tv_is_admin());
create policy "Admins read notifications" on public.tv_admin_notifications for select to authenticated using (public.tv_is_admin());
create policy "Admins update notifications" on public.tv_admin_notifications for update to authenticated using (public.tv_is_admin()) with check (public.tv_is_admin());
create or replace function public.admin_list_submissions() returns table (id uuid, owner_user_id uuid, first_name text, last_name text, credentials text, practice_name text, short_bio text, primary_city text, years_in_practice integer, website_url text, availability text, visit_types text[], specialties text[], services text[], approaches text[], status text, submitted_at timestamptz) language sql stable security definer set search_path='' as $$ select p.id,p.owner_user_id,p.first_name,p.last_name,p.credentials,p.practice_name,p.short_bio,p.primary_city,p.years_in_practice,p.website_url,p.availability,p.visit_types,p.specialties,p.services,p.approaches,pp.status,pp.submitted_at from public.provider_profiles p join public.provider_publication pp on pp.provider_id=p.id where public.tv_is_admin() and pp.status='submitted' order by pp.submitted_at asc; $$;
revoke all on function public.admin_list_submissions() from public, anon, authenticated; grant execute on function public.admin_list_submissions() to authenticated;
create or replace function public.admin_approve_provider(target_provider_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not public.tv_is_admin() then raise exception 'Administrator access required'; end if; update public.provider_publication set status='published', published_at=now(), last_verified_at=now() where provider_id=target_provider_id and status='submitted'; if not found then raise exception 'Submission is no longer awaiting review'; end if; end; $$;
create or replace function public.admin_request_provider_changes(target_provider_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not public.tv_is_admin() then raise exception 'Administrator access required'; end if; update public.provider_publication set status='draft' where provider_id=target_provider_id and status='submitted'; end; $$;
revoke all on function public.admin_approve_provider(uuid), public.admin_request_provider_changes(uuid) from public, anon, authenticated; grant execute on function public.admin_approve_provider(uuid), public.admin_request_provider_changes(uuid) to authenticated;
create or replace function public.tv_notify_submission() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.status='submitted' and (old.status is distinct from new.status) then insert into public.tv_admin_notifications(kind,provider_id) values('provider_submission',new.provider_id); end if; return new; end; $$;
drop trigger if exists tv_notify_submission on public.provider_publication; create trigger tv_notify_submission after update on public.provider_publication for each row execute function public.tv_notify_submission();
revoke all on function public.tv_notify_submission() from public, anon, authenticated;
commit;
